import{_ as o,o as t,c as n,a2 as a}from"./chunks/framework.CHeM0PsO.js";const g=JSON.parse('{"title":"Device Connector","description":"","frontmatter":{"epic":11,"title":"Device Connector","status":"✅ Complete — 11.1 (brightness) and 11.2 (torch) both done, both real-device-verified","scope":"mobile","sourceUrl":"https://github.com/sovereignfs/sovereign-edge/blob/main/docs/epics/mobile/device-connector.md"},"headers":[],"relativePath":"sovereign-edge/epics/mobile/device-connector.md","filePath":"sovereign-edge/epics/mobile/device-connector.md"}'),s={name:"sovereign-edge/epics/mobile/device-connector.md"};function r(i,e,c,d,l,h){return t(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="epic-device-connector" tabindex="-1">Epic: Device Connector <a class="header-anchor" href="#epic-device-connector" aria-label="Permalink to &quot;Epic: Device Connector&quot;">​</a></h1><blockquote><p>A first-party Tier 3 connector for simple, low-sensitivity on-device hardware toggles — flashlight and screen brightness.</p></blockquote><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Originally proposed as flashlight control plus alarm management. Research 0009 checked alarm creation/deletion against each platform&#39;s actual public API surface and found neither achievable as a silent, programmatic action — iOS exposes no alarm API to third-party apps at all, and Android&#39;s <code>AlarmClock</code> intents only hand off to whichever clock app is installed, with no way to enumerate or delete existing alarms. Alarms are dropped from scope entirely; see <a href="./../../research/0009-device-connector.html">research 0009</a> for the full findings.</p><p>Like <a href="./calendar-connector.html">Calendar</a>, this is a <strong>Tier 3</strong> connector — on-device native calls, not network requests — and depends on epic <a href="./connector-framework.html">2</a>&#39;s task 2.6 (Tier 3 scaffolding).</p><h2 id="tasks" tabindex="-1">Tasks <a class="header-anchor" href="#tasks" aria-label="Permalink to &quot;Tasks&quot;">​</a></h2><h4 id="✅-11-1-—-brightness" tabindex="-1">✅ 11.1 — Brightness <a class="header-anchor" href="#✅-11-1-—-brightness" aria-label="Permalink to &quot;✅ 11.1 — Brightness&quot;">​</a></h4><p><strong>Goal:</strong> Let the model read or set this app&#39;s own window brightness.</p><p><strong>Deliverables:</strong></p><ul><li>A Tier 3 connector manifest (per task 2.6&#39;s schema) declaring one tool, <code>device_set_brightness</code> — <code>value</code> is optional, so a call with no <code>value</code> is a read (reports the current brightness) and a call with <code>value</code> is a set-then-report, without needing a second manifest.</li><li>Via <code>expo-brightness</code>&#39;s app-window-scoped functions (<code>getBrightnessAsync</code>/<code>setBrightnessAsync</code>), not the system-wide variants. System-wide writes on Android require <code>WRITE_SETTINGS</code>, a special permission granted through a system settings screen rather than a normal runtime dialog; app-window brightness needs neither that nor any special permission on either platform — confirmed by reading <code>expo-brightness</code>&#39;s own doc comments, not assumed: only the system-wide functions mention anything permission-related.</li></ul><p><strong>Dependencies:</strong> Task 2.6 (Tier 3 scaffolding).</p><p><strong>Review checklist:</strong></p><ul><li>Asking the model to change brightness visibly does so, scoped to the app&#39;s own window.</li><li>Revoking this connector&#39;s permission does not affect any other connector&#39;s permission or vice versa.</li></ul><p><strong>Decided (during implementation):</strong></p><ul><li><strong>One manifest, not two.</strong> The original deliverable language (&quot;read/set screen brightness&quot;) could have read as two tools; <code>value</code> being optional covers both without a second manifest — simpler, and avoids the same read/write-capability-split question Calendar had to resolve, since here there&#39;s only one OS-level concern (app-window brightness, no special permission at all) rather than two.</li><li><strong>No OS permission step</strong>, unlike Calendar&#39;s <code>ensureCalendarAccess()</code> — <code>ConnectorsScreen.tsx</code>&#39;s default <code>grant()</code> path is used as-is for this row, since there&#39;s no OS dialog to gate before it.</li></ul><p><strong>Verified:</strong></p><ul><li><code>pnpm --filter mobile typecheck</code>/<code>lint</code>/<code>test</code> (308 tests, up from 293 — <code>device/manifest.test.ts</code>, <code>device/handlers.test.ts</code> (mocking <code>expo-brightness</code>), and new <code>ConnectorsScreen.test.tsx</code> cases).</li><li>Real iOS Simulator build (a real <code>pod install</code> linked the new <code>ExpoBrightness</code> native module) and launch, with a real tap through Settings → Connectors confirming the row renders from the real manifest and flips to <code>ALLOWED</code> (green, no OS permission dialog) on tap — matching the &quot;no OS permission step&quot; design decision above. A same-pass Calendar row independently stayed <code>NOT ASKED</code> with its denial banner, confirming no cross-connector state leakage.</li><li><strong>Honest gap:</strong> a live revoke round-trip (tapping the now-<code>ALLOWED</code> row back to <code>NOT ASKED</code>) was not separately captured on-device this pass — simulator tap coordinates became unreliable partway through this verification session (a recurring environment quirk, not a new one; see Calendar&#39;s own verification notes). Revoke uses the exact same <code>revoke()</code>/<code>refresh()</code> path already exercised for every other connector (Search, store connectors, Calendar) and is covered by a passing unit test (<code>ConnectorsScreen.test.tsx</code>&#39;s &quot;revokes a granted brightness connector on tap&quot;), so this is a real but low-risk gap, not a silent skip.</li></ul><hr><h4 id="✅-11-2-—-torch" tabindex="-1">✅ 11.2 — Torch <a class="header-anchor" href="#✅-11-2-—-torch" aria-label="Permalink to &quot;✅ 11.2 — Torch&quot;">​</a></h4><p><strong>Goal:</strong> Let the model turn the flashlight on/off.</p><p><strong>Why this shipped separately from 11.1:</strong> researching the actual <code>expo-camera</code> API before writing code found it has <strong>no imperative &quot;toggle the flashlight&quot; function at all</strong> — <code>enableTorch</code> only exists as a prop on a live, mounted <code>&lt;CameraView&gt;</code> (confirmed by reading the package&#39;s own type declarations). Every Tier 3 handler shipped before this (<code>device.info</code>, Calendar&#39;s four operations, 11.1&#39;s brightness) had been a plain function with zero UI-tree dependency; torch is the first one needing an actual camera session mounted somewhere in the app. On top of that, neither the iOS Simulator nor any environment used for the initial implementation pass had real flash hardware. Shipped as its own fast-follow once a physical iPhone became available in this environment, the same treatment Calendar&#39;s Windows/Linux gap (task 10.3) got for being deferred.</p><p><strong>Deliverables:</strong></p><ul><li>Requires the standard camera permission on both platforms even though nothing is captured or stored — a real OS permission step, same shape as Calendar&#39;s <code>ensureCalendarAccess()</code> (check status, prompt once if undetermined, gate the app&#39;s own <code>grant()</code> on a real <code>true</code> result): <code>permissions/cameraAccess.ts</code>&#39;s <code>ensureCameraAccess()</code>.</li><li><code>device.set_torch</code> tool, <code>on: boolean</code> (required — unlike brightness there is no meaningful &quot;read&quot; state for torch).</li></ul><p><strong>Dependencies:</strong> Task 2.6 (Tier 3 scaffolding); 11.1 (the manifest/handler shape to mirror, though torch&#39;s handler can&#39;t be a plain function the way every other one has been — see above).</p><p><strong>Review checklist:</strong></p><ul><li>Asking the model to turn on/off the flashlight visibly does so on a <strong>physical device</strong> — the iOS Simulator has no flash hardware, so this cannot be checked there.</li><li>Revoking this connector&#39;s permission does not affect any other connector&#39;s permission or vice versa.</li></ul><p><strong>Decided (during implementation):</strong></p><ul><li><strong>Where the live <code>&lt;CameraView&gt;</code> lives</strong> — the fork task 11.2 originally left open. Resolved as: mounted once, always, at the app root (<code>App.tsx</code>, alongside <code>&lt;StatusBar&gt;</code>), but only rendering an actual <code>&lt;CameraView&gt;</code> once camera permission is known granted — checked once on <code>TorchHost.tsx</code>&#39;s own mount (covers a connector granted in an earlier app session) and updated live via a small new bridge module, <code>connectors/device/torchBridge.ts</code>, whose <code>notifyCameraPermissionGranted()</code> the <code>setTorch</code> handler calls right after <code>ensureCameraAccess()</code> resolves <code>granted: true</code>. This sidesteps needing a general &quot;connector grant changed&quot; event system — nothing else in the app has one, and building one just for this would have been a bigger, separate change — while still keeping the camera session at zero cost for anyone who never grants this connector (no permission, no session, regardless of mount).</li><li><code>torchBridge.ts</code> also holds the <code>TorchController</code>/<code>setTorchController</code> pair (<code>setTorch(on)</code> → local component state → <code>enableTorch</code> prop) — the one genuinely new pattern in this codebase&#39;s connector runtime, since every other <code>NativeHandler</code> is a pure function with no relationship to anything mounted in the component tree.</li><li>No torch readback API exists (unlike brightness&#39;s <code>getBrightnessAsync</code>), so <code>setTorch</code>&#39;s reported text is optimistic — it reflects what was requested, not a re-read confirmation.</li></ul><p><strong>Two real bugs found and fixed during physical-device verification</strong> — neither was visible in any Simulator run or unit test; both only surfaced once this connector was actually installed and launched on real hardware:</p><ol><li><strong>The app crashed on launch (<code>SIGABRT</code>) on the physical iPhone, before reaching the home screen.</strong> Root cause: <code>apps/mobile/ios/</code> — gitignored, generated output — had never been regenerated via <code>npx expo prebuild</code> since the <code>expo-calendar</code> and <code>expo-camera</code> config-plugin entries were added to <code>app.json</code>; only <code>pod install</code> had been run, which links native code but does not apply config plugins. <code>Info.plist</code> was therefore missing <code>NSCameraUsageDescription</code> entirely (and, it turned out, <code>NSCalendarsUsageDescription</code>/<code>NSCalendarsFullAccessUsageDescription</code> too — Calendar&#39;s own physical-device verification had only ever run on the Simulator, which tolerates this differently). Mounting <code>&lt;CameraView&gt;</code> without the required Info.plist key hard-crashes on real hardware. Fixed with <code>npx expo prebuild --clean --platform ios</code> (regenerates <code>ios/</code> from <code>app.json</code>) followed by the already-established <code>LANG=en_US.UTF-8 LC_ALL=en_US.UTF-8 pod install</code> fix for this environment&#39;s CocoaPods Unicode bug.</li><li><strong>The first real grant reported success but the flashlight never lit.</strong> Root cause: with <code>TorchHost</code> originally mounting <code>&lt;CameraView&gt;</code> unconditionally at app launch — before any camera permission existed — the native capture session did not retroactively start once permission was granted later in the session; nothing told the already-mounted view to reconfigure. Fixed by the permission-gated mount + notify-on-grant bridge described above.</li></ol><p><strong>Observed, explicitly out of scope:</strong> the model sometimes asked for the <code>on</code> argument more than once in chat before actually calling <code>device_set_torch</code>, even though the tool call ultimately succeeded and the flashlight worked correctly once invoked. This is model tool-calling behavior, not a torch defect — confirmed with the user, who has a separate plan for that and asked it not be addressed here.</p><p><strong>Verified:</strong></p><ul><li><code>pnpm --filter mobile typecheck</code>/<code>lint</code>/<code>test</code> (338 tests, up from 329 — <code>torchBridge.test.ts</code>, <code>permissions/cameraAccess.test.ts</code>, <code>device/TorchHost.test.tsx</code>, extended <code>device/handlers.test.ts</code> and <code>device/manifest.test.ts</code>, extended <code>ConnectorsScreen.test.tsx</code>).</li><li>Real <code>pnpm install</code> + <code>pod install</code> linked the new <code>ExpoCamera</code> native module (98 dependencies, up from 96).</li><li>Real physical iPhone (a real device connected to this environment, not the Simulator) build via <code>xcodebuild ... -destination &#39;id=&lt;udid&gt;&#39; -allowProvisioningUpdates build</code>, installed and launched via <code>xcrun devicectl device install app</code> / <code>process launch</code> — the same sequence 11.1 used, extended here because 11.2 specifically needs real flash hardware to mean anything.</li><li>After fixing both bugs above: a real OS camera-permission dialog appeared on tapping the &quot;Device — Flashlight&quot; row, the row flipped to <code>ALLOWED</code>, and — confirmed directly by the user on the physical device, not simulated or assumed — asking the assistant in chat to turn the flashlight on and back off actually toggled the hardware flash both times.</li><li><strong>Honest gap:</strong> a live revoke round-trip (tapping the now-<code>ALLOWED</code> row back off) was not separately re-confirmed on this physical device after the fixes — it uses the same <code>revoke()</code>/<code>refresh()</code> path exercised for every other connector and is covered by a passing unit test (<code>ConnectorsScreen.test.tsx</code>&#39;s torch <code>describe</code> block), the same low-risk gap 11.1 documented for the same reason.</li></ul><p><strong>Explicitly out of scope (both 11.1 and 11.2):</strong> alarm creation, listing, or deletion — see research 0009&#39;s findings; not a gap to close later, a capability that doesn&#39;t meaningfully exist to build against on either platform.</p><h2 id="related-docs" tabindex="-1">Related Docs <a class="header-anchor" href="#related-docs" aria-label="Permalink to &quot;Related Docs&quot;">​</a></h2><ul><li><a href="./../../research/0001-concept-and-connector-architecture.html">research 0001</a></li><li><a href="./../../research/0009-device-connector.html">research 0009</a></li><li><a href="./connector-framework.html">Connector Framework</a> (task 2.6, the Tier 3 scaffolding this epic depends on)</li></ul><h2 id="cross-references" tabindex="-1">Cross-references <a class="header-anchor" href="#cross-references" aria-label="Permalink to &quot;Cross-references&quot;">​</a></h2><ul><li>Shares its Tier 3 dependency (task 2.6) with the <a href="./calendar-connector.html">Calendar connector</a> (epic 10).</li></ul>',38)])])}const u=o(s,[["render",r]]);export{g as __pageData,u as default};
